//autogenerated:yes
//nolint:revive,govet,errcheck
package common_test

import (
	"testing"

	"github.com/stretchr/testify/require"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/common"
)

func TestEnum_VTOL_TRANSITION_HEADING(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.VTOL_TRANSITION_HEADING
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.VTOL_TRANSITION_HEADING_VEHICLE_DEFAULT.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.VTOL_TRANSITION_HEADING
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.VTOL_TRANSITION_HEADING_VEHICLE_DEFAULT, dec)
	})
}
